package hu.synostream.android;
import java.io.*;import java.util.*;import java.nio.charset.StandardCharsets;import org.junit.Test;import static org.junit.Assert.*;
/** Independent randomized EBML checksum oracle. Production MatroskaAudio is read-only in this task. */
public class MatroskaCrcAuditTest {
 static byte[] join(List<byte[]> parts)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();for(byte[] p:parts)out.write(p);return out.toByteArray();}
 static byte[] element(int id,byte[] data)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();int width=id>0xffffff?4:id>0xffff?3:id>0xff?2:1;for(int i=width-1;i>=0;i--)out.write(id>>(8*i));int sizeWidth=1;while(data.length>=(1L<<(7*sizeWidth))-1)sizeWidth++;long size=data.length|(1L<<(7*sizeWidth));for(int i=sizeWidth-1;i>=0;i--)out.write((int)(size>>(8*i)));out.write(data);return out.toByteArray();}
 static byte[] withCrc(List<byte[]> fields,Random random)throws Exception{byte[] data=join(fields);java.util.zip.CRC32 checksum=new java.util.zip.CRC32();checksum.update(data);long sum=checksum.getValue();byte[] bytes={(byte)sum,(byte)(sum>>8),(byte)(sum>>16),(byte)(sum>>24)};List<byte[]> result=new ArrayList<>(fields);result.add(random.nextInt(result.size()+1),element(0xbf,bytes));return join(result);}
 static byte[] track(int number,Random random)throws Exception{List<byte[]> fields=new ArrayList<>();fields.add(element(0xd7,new byte[]{(byte)number}));fields.add(element(0x83,new byte[]{2}));fields.add(element(0x86,"A_AC3".getBytes(StandardCharsets.US_ASCII)));fields.add(element(0x22b59c,new String[]{"hun","eng","jpn","deu"}[random.nextInt(4)].getBytes(StandardCharsets.US_ASCII)));if(random.nextBoolean())fields.add(element(0x88,new byte[]{(byte)random.nextInt(2)}));if(random.nextBoolean())fields.add(element(0xb9,new byte[]{1}));byte[] padding=new byte[5+random.nextInt(300)];random.nextBytes(padding);fields.add(element(0xec,padding));Collections.shuffle(fields,random);return element(0xae,withCrc(fields,random));}
 static long bitwiseCrc(byte[] b,int start,int end,int skipStart,int skipEnd){long crc=0xffffffffL;for(int p=start;p<end;p++){if(p>=skipStart&&p<skipEnd)continue;crc^=b[p]&255;for(int n=0;n<8;n++)crc=(crc>>>1)^((crc&1)==0?0:0xedb88320L);}return (crc^0xffffffffL)&0xffffffffL;}
 static long read(byte[] bytes,int[] at,boolean size){int first=bytes[at[0]++]&255,width=1,mask=128;while((first&mask)==0){mask>>=1;width++;}long value=size?first&(mask-1):first;for(int n=1;n<width;n++)value=(value<<8)|(bytes[at[0]++]&255);return value;}
 static int verify(byte[] bytes,int begin,int end){int count=0;int[] cursor={begin};while(cursor[0]<end){int start=cursor[0];long id=read(bytes,cursor,false),size=read(bytes,cursor,true);int data=cursor[0],next=data+(int)size;assertTrue(next<=end);if(id==0xbf){assertEquals(4,size);long actual=0;for(int n=0;n<4;n++)actual|=(long)(bytes[data+n]&255)<<(8*n);assertEquals("CRC scope "+begin+":"+end,bitwiseCrc(bytes,begin,end,start,next),actual);count++;}else if(id==0x18538067L||id==0x1654ae6bL||id==0xae)count+=verify(bytes,data,next);cursor[0]=next;}return count;}
 @Test public void randomNestedCrcHeadersStayValidForEveryAudioChoice()throws Exception{Random random=new Random(0x52c0ffeeL);int choices=0;for(int sample=0;sample<200;sample++){int number=2+random.nextInt(5);List<byte[]> fields=new ArrayList<>();for(int n=1;n<=number;n++)fields.add(track(n,random));byte[] tracks=element(0x1654ae6b,withCrc(fields,random));byte[] header=join(List.of(new byte[]{0x18,0x53,(byte)0x80,0x67,(byte)0xff},tracks));assertEquals(number+1,verify(header,5,header.length));List<MatroskaAudio.Track> inspected=MatroskaAudio.inspect(header);assertEquals(number,inspected.size());for(int chosen=1;chosen<=number;chosen++){byte[] patched=header.clone();Map<Long,Byte> patch=MatroskaAudio.select(inspected,chosen);assertFalse(patch.isEmpty());MatroskaAudio.patch(patched,patched.length,0,patch);assertEquals(header.length,patched.length);assertEquals(number+1,verify(patched,5,patched.length));choices++;}}assertTrue(choices>=400);}
 @Test public void segmentWideChecksumCausesSafeNoPatchAndStaysValid()throws Exception{Random random=new Random(52);byte[] tracks=element(0x1654ae6b,withCrc(List.of(track(1,random),track(2,random)),random));byte[] header=element(0x18538067,withCrc(List.of(tracks),random));assertEquals(4,verify(header,0,header.length));Map<Long,Byte> patch=MatroskaAudio.select(MatroskaAudio.inspect(header),2);assertTrue(patch.isEmpty());MatroskaAudio.patch(header,header.length,0,patch);assertEquals(4,verify(header,0,header.length));}
}
